import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>كل صورة على الويب توجد في أحد شكلين: ملف له اسم ورابط، أو سلسلة Base64 مضمّنة في الكود. الشكلان يحملان نفس البكسلات، لكنهما يتصرفان بشكل مختلف تمامًا.</p>\n<p>اختيار الشكل الخاطئ يكلف الأداء ويهدر النطاق الترددي أو يحوّل تحديثًا بسيطًا إلى مهمة مؤلمة. واختيار الشكل الصحيح يتعلق غالبًا بمعرفة ما يجيد كل منهما.</p>\n<p>يقارن هذا المقال سلاسل Base64 وملفات الصور وجهًا لوجه: الحجم والسرعة والتخزين المؤقت والتحرير وحالات الاستخدام التي يفوز فيها كل منهما بوضوح.</p>\n<h2 id=\"two-ways-to-store-an-image\">طريقتان لحفظ الصورة نفسها</h2>\n<p>ملف الصورة بيانات ثنائية لها اسم وصيغة وموقع. يجلبه المتصفح بطلب ويخزنه مؤقتًا ويعرضه كلما أشارت إليه الصفحة.</p>\n<p>أما سلسلة Base64 فهي نفس البيانات الثنائية مكتوبة كنص. تعيش داخل HTML أو CSS أو JSON أو قاعدة بيانات، ويفكها المتصفح فورًا دون أي طلب. والبكسلات متطابقة في الشكلين.</p>\n<h2 id=\"size-comparison\">الحجم: فجوة 33 بالمئة</h2>\n<p>سلسلة Base64 أكبر بنحو 33 بالمئة من الملف الذي ترمّزه. صورة 90 كيلوبايت تتحول إلى سلسلة 120 كيلوبايت، وصورة 1 ميغابايت تتحول إلى سلسلة 1.4 ميغابايت.</p>\n<p>الفجوة خاصية ثابتة في الترميز: أربعة أحرف نصية تحمل ثلاثة بايتات من البيانات، فالسلسلة تحتاج دائمًا ثلثًا إضافيًا من الأحرف. وبالنسبة للصور الصغيرة تكون الفجوة تافهة، أما للصور الكبيرة فهي تهيمن على القرار.</p>\n<h2 id=\"performance-loading\">الأداء: سرعة التحميل</h2>\n<p>الصورة المرتبطة تكلف طلبًا لكنها تُعرض تدريجيًا. المتصفح يعرض النص أولًا ويكمل الصورة عند وصولها، فتبدو الصفحة سريعة حتى على اتصال بطيء.</p>\n<p>أما الصورة المضمّنة كـBase64 فلا تكلف أي طلب لكنها تحجب العرض. يجب على المتصفح تنزيل مستند HTML كاملًا، بما فيه السلسلة، قبل عرض أي شيء. لصفحة فيها أيقونة صغيرة يكون التضمين أسرع، أما لصفحة فيها صور كثيرة أو كبيرة فالربط أسرع.</p>\n<h2 id=\"caching\">التخزين المؤقت: الفرق الحاسم</h2>\n<p>التخزين المؤقت هو المكان الذي تفوز فيه ملفات الصور بشكل حاسم. الملف المرتبط يُنزَّل مرة واحدة ويُعاد استخدامه في كل صفحة تشير إليه، طالما سمحت الترويسات بذلك.</p>\n<p>أما سلسلة Base64 فتُنزَّل من جديد مع كل صفحة تحتويها. شعار مضمّن في خمسين صفحة يكلف خمسين تنزيلًا، بينما نفس الشعار مربوطًا يكلف تنزيلًا واحدًا. وهذا هو أكبر سبب لتفضيل الملفات للصور المشتركة.</p>\n<h2 id=\"portability\">قابلية النقل: نقل الصور</h2>\n<p>سلاسل Base64 تسافر داخل النص، ما يجعلها قابلة للنقل بطرق لا تستطيعها الملفات. يمكن لصق السلسلة في رسالة محادثة أو حفظها في صف قاعدة بيانات أو تضمينها في ملف JSON.</p>\n<p>ملفات الصور تحتاج إلى موقع: رابط أو مجلد أو مرفق. نقل ملف يعني نقل مرجعه أيضًا، والمرجع المكسور ينتج صورة مكسورة. وواجهات API هي أوضح حالة للسلاسل، لأن JSON لا يستطيع حمل بيانات ثنائية.</p>\n<h2 id=\"editing-and-versioning\">التحرير والتحكم في الإصدارات</h2>\n<p>تحديث صورة مرتبطة هو تبديل ملف. استبدل الملف واحتفظ بالاسم، وكل صفحة تشير إليه تعرض النسخة الجديدة فورًا.</p>\n<p>أما تحديث صورة مضمّنة فيعني العثور على السلسلة واستبدال جدار من النص والأمل بأنك استبدلت الصحيحة. والتحكم في الإصدارات يعاني مع السلاسل، لأن تغيير صورة من سطر واحد يتحول إلى فرق من ألف سطر يغرق التغييرات الحقيقية.</p>\n<h2 id=\"search-and-accessibility\">البحث وسهولة الوصول والمشاركة</h2>\n<p>محركات البحث تفهرس ملفات الصور المرتبطة وتعرضها في بحث الصور. الصورة المضمّنة كـBase64 غير مرئية غالبًا لذلك النظام، فلا تجلب زيارات من بحث الصور.</p>\n<p>قارئات الشاشة وأدوات سهولة الوصول تعمل مع الشكلين، لكن فقط عندما يكون الوسم صحيحًا: عنصر الصورة يحتاج سمة alt سواء كان مصدره ملفًا أو سلسلة. كما أن معاينات المشاركة الاجتماعية تفضل الملفات، فالصفحة التي تعتمد على صور مضمّنة قد لا تعرض أي صورة مصغرة عند مشاركتها.</p>\n<h2 id=\"api-and-data-transfer\">API ونقل البيانات</h2>\n<p>واجهات API التي تقبل JSON تتوقع الصور كسلاسل Base64، لأن JSON لا يملك نوعًا ثنائيًا. تسافر السلسلة في حقل ويفكها الخادم ويعيد بناء الملف على الطرف الآخر.</p>\n<p>الرفع متعدد الأجزاء هو البديل القائم على الملفات، وهو أكفأ للصور الكبيرة. يرسل طلبًا ثنائيًا مباشرة دون زيادة 33 بالمئة. اختر Base64 للصور الصغيرة في تدفقات JSON مثل الصور الرمزية والتوقيعات، واختر الرفع متعدد الأجزاء للصور الكبيرة.</p>\n<h2 id=\"email-use-cases\">البريد: السلاسل تفوز في الصغير والملفات في الكبير</h2>\n<p>رسائل البريد رسائل منفردة، فالصورة المضمّنة تسافر مع النص وتظهر حتى عندما يكون القارئ دون اتصال. هذه ميزة حقيقية أمام الصورة المرتبطة التي قد لا تظهر أبدًا.</p>\n<p>الصور الصغيرة تُضمَّن جيدًا في البريد: الشعارات والأيقونات واللافتات الصغيرة أقل من 10 كيلوبايت. أما الصور الفوتوغرافية الكبيرة فأبقها مربوطة أو اتركها خارجًا، لأن الصورة المضمّنة الثقيلة تجعل الرسالة بطيئة الفتح، وبعض خوادم البريد ترفض الرسائل فوق حد معين.</p>\n<h2 id=\"security-considerations\">اعتبارات الأمان</h2>\n<p>سلسلة Base64 تخفي محتواها عن الفحص العارض. المراجع الذي يمسح الكود لا يستطيع رؤية ما تُظهره الصورة دون فكها، ما يجعل مراجعة الأمان أصعب.</p>\n<p>ترويسات سياسة أمان المحتوى قد تحجب روابط البيانات، فالسياسة الصارمة التي تسمح بالصور من نطاقك فقط سترفض الصورة المضمّنة ما لم يُسمح بـdata: صراحة. وملفات الصور أسهل في التدقيق: يمكن مسح الملف وتجزئته والتحقق منه.</p>\n<h2 id=\"when-files-win\">متى تفوز ملفات الصور بوضوح</h2>\n<p>ملفات الصور تفوز للصور الفوتوغرافية وشعارات الموقع كله وأي شيء فوق 50 كيلوبايت. توفير التخزين المؤقت وسرعة العرض يفوقان توفير الطلبات بكثير.</p>\n<p>والملفات تفوز للصور التي تتغير وللصور التي تحتاج أن تُعثر عليها وللفرق. المصمم يستطيع استبدال ملف دون لمس الكود، والمطور يستطيع مراجعة التغيير دون ألم، وسجل الإصدارات يبقى مقروءًا.</p>\n<h2 id=\"when-strings-win\">متى تفوز سلاسل Base64 بوضوح</h2>\n<p>السلاسل تفوز لمستندات الملف الواحد التي يجب أن تعمل دون اتصال. تقرير HTML أو صفحة ويب محفوظة أو بريد لا يستطيع جلب ملفات خارجية، فالتضمين هو الطريقة الوحيدة.</p>\n<p>والسلاسل تفوز للأيقونات الصغيرة أقل من 2 كيلوبايت ولحمولات JSON وحقول قواعد البيانات وللصور المولدة دون موطن. الصورة المنشأة لحظيًا بواسطة سكربت يمكن تضمينها فورًا دون حفظها أولًا على خادم والحصول على رابط.</p>\n<h2 id=\"hybrid-approach\">النهج الهجين</h2>\n<p>معظم المشاريع الحقيقية تستخدم الشكلين. الأيقونات الصغيرة تُضمَّن والصور الفوتوغرافية تُربط وحمولات API تحمل Base64 بينما يخدم الموقع ملفات.</p>\n<p>القاعدة الهجينة بسيطة: ضمّن ما هو صغير وأساسي، واربط ما هو كبير أو مشترك، واستخدم السلاسل حيث يكون النقل قائمًا على النص. ووثّق الاختيار حسب نوع الصورة لا حسب الصورة، وراجع القاعدة عندما يتغير المشروع.</p>\n<h2 id=\"migration-checklist\">كيف تنتقل بين الشكلين</h2>\n<p>الانتقال من السلاسل إلى الملفات بسيط. فك السلسلة بمفكك Base64 إلى صورة واحفظ الملف وارفعه واستبدل السلسلة برابطه.</p>\n<p>والانتقال من الملفات إلى السلاسل سهل بالقدر نفسه. رمّز الملف بمرمّز الصورة إلى Base64 وانسخ الناتج والصقه حيث كان الرابط. ونفّذ الانتقال نوع صورة واحدًا في كل مرة، وقِس قبل وبعد.</p>\n<h2 id=\"cost-bandwidth-storage\">التكلفة: النطاق الترددي والتخزين</h2>\n<p>النطاق الترددي هو التكلفة الأكثر واقعية لاختيار Base64. صفحة فيها 1 ميغابايت من الصور المضمّنة تنقل نحو 1.33 ميغابايت من بيانات الصور، بينما نفس الصور المرتبطة تنقل 1 ميغابايت فقط.</p>\n<p>على اتصال جوال محسوب، الثلث الإضافي مال حقيقي للقارئ. والتخزين يتبع النسبة نفسها: قاعدة بيانات تحفظ 10 غيغابايت من الصور كـBase64 تحفظ 13.3 غيغابايت من النص، وكل نسخة احتياطية ونسخ متماثل وترحيل يحمل الوزن الإضافي.</p>\n<h2 id=\"quick-reference\">مرجع سريع: السلاسل أم الملفات</h2>\n<p>استخدم ملفات الصور للصور الفوتوغرافية والشعارات المشتركة والصور الكبيرة وأي شيء يحتاج تخزينًا مؤقتًا أو فهرسة في البحث أو تحديثات متكررة.</p>\n<p>استخدم سلاسل Base64 للأيقونات الصغيرة ومستندات الملف الواحد والبريد وحمولات JSON، حيث يجعل النقل القائم على النص الملفات مستحيلة أو غير عملية. وللأدوات، استخدم <a href=\"/ar/tahwil-as-sura-ila-base64/\">مرمّز الصورة إلى Base64</a> و<a href=\"/ar/tahwil-base64-ila-sura/\">مفكك Base64 إلى صورة</a>. ولإطار قرار التضمين، اقرأ <a href=\"/ar/blog/suwar-base64-mata-tudamman/\">صور Base64: متى تضمّنها ومتى لا</a> وخطوات <a href=\"/ar/blog/kayfiyya-tahwil-as-sura-ila-base64/\">كيف تحوّل صورة إلى Base64</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل صورة Base64 تُحمَّل أبطأ من ملف صورة عادي؟","answer":"يعتمد على الحجم والسياق. أيقونة صغيرة مضمّنة تُحمَّل أسرع لأنها توفر طلبًا، بينما صورة كبيرة مضمّنة تُحمَّل أبطأ لأنها تحجب العرض ولا يمكن تخزينها مؤقتًا بشكل منفصل."},{"question":"هل يمكنني تحويل سلسلة Base64 إلى ملف واستضافته بشكل طبيعي؟","answer":"نعم، الصق السلسلة في مفكك Base64 إلى صورة ونزّلها كأصلية أو PNG أو JPG أو WebP وارفع الملف إلى خادمك. استبدل السلسلة المضمّنة برابط الملف، فتصبح الصورة ملفًا عاديًا."},{"question":"هل صور Base64 تعمل في كل المتصفحات؟","answer":"روابط البيانات تعمل في كل المتصفحات الحديثة، بما فيها كروم وسفاري وفايرفوكس وإيدج. المتصفحات القديمة جدًا كانت لها حدود حجم في روابط البيانات، لكن هذه الحدود اختفت في الإصدارات الحديثة."},{"question":"لماذا أصبحت صفحتي بطيئة بعد تضمين عدة صور؟","answer":"لأن السلاسل المضمّنة جعلت مستند HTML أكبر بكثير، ويجب على المتصفح تنزيله كاملًا قبل عرضه. كل صورة تكلف أيضًا 33 بالمئة بايتات إضافية مقارنة بالملف. أعد ربط الصور الكبيرة كملفات."},{"question":"هل سلاسل Base64 آمنة لحفظ صور المستخدمين الرمزية في قاعدة بيانات؟","answer":"إنها مريحة لكنها ليست آمنة بطبيعتها. Base64 ترميز لا تشفير، فأي شخص لديه وصول إلى قاعدة البيانات يستطيع فك السلسلة والحصول على الصورة. احفظ الصور الرمزية كملفات في تخزين كائنات مع مرجع في قاعدة البيانات."},{"question":"متى أستخدم الرفع متعدد الأجزاء بدل Base64 في API؟","answer":"استخدم الرفع متعدد الأجزاء للصور الكبيرة، لأنه يرسل الثنائي مباشرة دون زيادة 33 بالمئة. واستخدم Base64 عندما تقبل API JSON فقط أو عندما تكون الصورة صغيرة أو عندما لا يستطيع العميل إرسال بيانات متعددة الأجزاء."}];
